using Microsoft.EntityFrameworkCore;
using Shouldly;
using Store.Application.Products.Requests;
using Store.Application.Products.Services;
using Store.Infrastructure.Persistence;

namespace Store.Infrastructure.Tests.Catalog;

/// <summary>
/// SQL generated by the product query helpers (research R9). <c>ToQueryString</c> needs the SQL
/// Server provider but no connection, so no database is created.
/// </summary>
public class ProductQueryExtensionsTests
{
    private static AppDbContext CreateContext() =>
        new(new DbContextOptionsBuilder<AppDbContext>()
            .UseSqlServer("Server=unused;Database=unused;Integrated Security=true")
            .Options);

    [Fact]
    public void ApplySearch_SendsAnEscapedParameter_NeverTheRawTerm()
    {
        using var context = CreateContext();

        var sql = context.Products.ApplySearch("50%_[X").ToQueryString();

        sql.ShouldContain("LIKE");
        sql.ShouldContain("ESCAPE N'\\'");
        sql.ShouldContain("LOWER(");
        sql.ShouldContain(@"50\%\_\[x");
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("   ")]
    public void ApplySearch_EmptyTerm_LeavesQueryUnchanged(string? search)
    {
        using var context = CreateContext();
        var products = context.Products.AsQueryable();

        products.ApplySearch(search).ShouldBeSameAs(products);
    }

    [Fact]
    public void ApplyVariantFilters_NoNames_LeavesQueryUnchanged()
    {
        using var context = CreateContext();
        var products = context.Products.AsQueryable();

        products.ApplyVariantFilters([], ["  "]).ShouldBeSameAs(products);
    }

    [Fact]
    public void ApplyVariantFilters_UsesOneVariantForColorAndSize()
    {
        using var context = CreateContext();

        var sql = context.Products.ApplyVariantFilters(["Black"], ["XL"]).ToQueryString();

        // One EXISTS over variants with both conditions, values sent as parameters.
        sql.Split("EXISTS").Length.ShouldBe(2);
        sql.ShouldContain("[Stock] > 0");
        CountOccurrences(sql, "@colorNames").ShouldBeGreaterThan(1, "declared and used as a parameter");
        CountOccurrences(sql, "@sizeNames").ShouldBeGreaterThan(1, "declared and used as a parameter");
    }

    private static int CountOccurrences(string text, string value) =>
        text.Split(value, StringSplitOptions.None).Length - 1;

    [Fact]
    public void ApplySort_UnknownValue_Throws()
    {
        using var context = CreateContext();

        Should.Throw<ArgumentOutOfRangeException>(() => context.Products.ApplySort((ProductSort)99));
    }
}
